            'site_favicon' => 'Website-Favicon (.ico). Es wird z. B. für Lesezeichen verwendet. Empfohlene Größe: 16px * 16px',
            'site_skin' => 'Wählen Sie die Designfarbe der Website. Beim Design „Modern“ wird die Farbe der Kopfzeile als Akzentfarbe für Schaltflächen, Links, das ausgewählte Menü usw. verwendet; die Kopfzeile bleibt weiß und die Seitenleiste hellgrau, daher sehen „Seitenleiste: schwarz“ und „Seitenleiste: weiß“ gleich aus. *Nach dem Speichern wird die Änderung beim Neuladen übernommen.',
            'site_layout' => 'Wählen Sie das Layout des Website-Menüs auf der linken Seite. *Nach dem Speichern wird die Änderung beim Neuladen übernommen.',
            'ui_design' => 'Wählen Sie das Design der Anmeldeseite und der Verwaltungsseiten. „Modern“ ist das neue Design in Weiß und Grau, „Klassisch“ ist das bisherige Design. Standard ist „Modern“. Um zum bisherigen Design zurückzukehren, wählen Sie „Klassisch“. *Nach dem Speichern wird die Änderung beim Neuladen übernommen.<br/>Wenn das Design durch den Server festgelegt ist (EXMENT_UI_DESIGN in .env), hat dieser Wert Vorrang und kann hier nicht geändert werden.',
            'filter_search_type' => 'Legt die Suchmethode für registrierte Daten fest. *Bei der Teiltreffersuche kann die Performance je nach Datenmenge beeinträchtigt werden.',
            'grid_filter_disable_flg' => 'Die markierten Elemente werden in den Filterelementen der Datenliste ausgeblendet.',
            'system_values_pos' => 'Legt fest, an welcher Position die Systemwerte auf dem Bearbeitungs- und Detailbildschirm der Daten angezeigt werden.',
            'data_submit_redirect' => 'Sie können festlegen, zu welcher Seite standardmäßig nach dem Speichern benutzerdefinierter Daten weitergeleitet wird. Wenn diese Option gesetzt ist, ist auf der Dateneingabeseite das entsprechende Kontrollkästchen für das Ziel nach dem Speichern bereits aktiviert.',
            'header_user_info' => 'Sie können festlegen, welche Inhalte in den Benutzerinformationen in der Kopfzeile angezeigt werden. Wenn das Feld leer bleibt, werden sie ausgeblendet.',
            'allowed_locales' => 'Die Sprachen, die die Benutzer im Menü oben rechts, auf der Anmeldeseite und in ihren Einstellungen wählen können. Leer bedeutet alle installierten Sprachen. Die Sprache der Website kann immer gewählt werden.',
            'locale_from_browser' => 'Bei JA sieht ein Benutzer, der keine Sprache gewählt hat, die Seiten in der Sprache des Browsers (unter den wählbaren Sprachen). Bei NEIN in der Sprache der Website.',
            'grid_inline_edit_available' => 'Bei JA kann ein Wert direkt in der Datenliste geändert werden, per Doppelklick auf eine Zelle oder Klick auf das Stiftsymbol. Bei NEIN wird die Inline-Bearbeitung in keiner Datenliste verwendet. Die Massenbearbeitung und die Bearbeitungsseite der Daten bleiben wie bisher verfügbar.',
            'api_available' => 'Bitte erstellen Sie einen Laravel-Schlüssel, bevor Sie JA wählen. Weitere Informationen finden Sie <a href="%suse-api" target="_blank">hier<i class="fa fa-external-link"></i></a>. Bei JA können Sie die API verwenden.',
            'outside_api' => 'Bei JA können Vorgänge mit externer Serverkommunikation ausgeführt werden, z. B. die Benachrichtigung über die neueste Exment-Version. Es werden nur Daten empfangen. * Wenn keine Kommunikation erfolgen soll, z. B. in einer Umgebung ohne Verbindung zu einem externen Netzwerk, wählen Sie NEIN.',
            'grid_pager_count' => 'Standardanzahl der auf der Listenseite angezeigten Einträge. Gilt für das gesamte System.',
