            'meili_host' => 'z. B. http://127.0.0.1:7700',
            'meili_key' => 'Master-API-Schlüssel des Meilisearch-Servers. Wird verschlüsselt gespeichert. Wenn Sie dieses Feld leeren, wird ein leerer Schlüssel gespeichert und stattdessen der Wert MEILISEARCH_KEY aus .env verwendet.',
