        'kanban_labels_style_options' => [
            'chip' => 'Chip mit Text',
            'bar' => 'Nur Farbbalken',
        ],
        'description_custom_view_columns' => 'Wählen Sie die anzuzeigenden Spalten aus.',
        'description_custom_view_kanban_columns' => 'Wählen Sie die auf der Karte angezeigten Spalten aus. „Position“ bestimmt, wo sie auf der Karte erscheinen, „Stil“ wählt eine Darstellungsvorlage für Zellen (Tag, Pille, Badge usw.) – dieselbe Bibliothek wie in der Datenliste, sodass ein Aussehen nur einmal festgelegt und auf beiden Seiten verwendet wird.<br/>*Bleibt „Stil“ leer, folgt die Karte der Spalteneinstellung; gibt es dort keine, wird „Name und Wert“ angezeigt.<br/>*Unter „Symbol“ geben Sie einen Font-Awesome-Klassennamen ein (zum Beispiel fa-phone). Durch Kommas getrennte Paare „Wert:Klasse“ geben jedem Wert ein eigenes Symbol.<br/>*Ist nichts festgelegt, zeigt die Karte nur den Titel.<br/>*Eine Spalte, die als Label (farbig), Frist (SLA-Timer) oder Badge-Spalte festgelegt ist, wird an der jeweiligen Stelle angezeigt und daher nicht noch einmal im Kartentext angezeigt.',
        'description_custom_view_calendar_columns' => 'Wählen Sie die Datumsspalte aus, die im Kalender angezeigt werden soll.<br/>* Wenn benutzerdefinierte Spalten unter „Zielspalte“ nicht erscheinen, wurde kein <a href="%s" target="_blank">Suchindex<i class="fa fa-external-link"></i></a> festgelegt. Bitte prüfen Sie den Inhalt des Linkziels und nehmen Sie die Einstellung vor.',
        'description_custom_view_groups' => 'Legt die Spalten fest, die als Schlüssel für die Gruppierung der Ansicht dienen.<br />*Wenn benutzerdefinierte Spalten unter „Zielspalte“ nicht erscheinen, wurde der <a href="%s" target="_blank">Suchindex<i class="fa fa-external-link"></i></a> nicht festgelegt. Bitte prüfen Sie den Inhalt des Linkziels und nehmen Sie die Einstellung vor.',
        'description_custom_view_summaries' => 'Legt die Summenspalten der in der Ansicht angezeigten Daten fest.<br/>*Ausgewertet werden Spalten vom Typ „ID“, „Ganzzahl“, „Dezimalzahl“, „Währung“ und „Datum“. Um die Gesamtzahl der Datensätze zu ermitteln, wählen Sie als Zielspalte „ID“ und als Summentyp „Anzahl“.',
        'description_custom_view_sorts' => 'Legt die Reihenfolge der in der Ansicht angezeigten Daten fest.<br/>*Wenn Sie zwei oder mehr Sortierungen festlegen, kann sich die Leistung bei Tabellen mit sehr vielen Daten verschlechtern. Wenn benutzerdefinierte Spalten unter „Zielspalte“ nicht erscheinen, wurde der <a href="%s" target="_blank">Suchindex<i class="fa fa-external-link"></i></a> nicht festgelegt. Bitte prüfen Sie den Inhalt des Linkziels und nehmen Sie die Einstellung vor.',
        'description_custom_view_filters' => 'Legen Sie die Bedingungen für die in der Ansicht angezeigten Daten fest.<br/>* Zusätzlich zu dieser Einstellung werden die Daten so gefiltert, dass nur Daten angezeigt werden, für die der Login-Benutzer eine Berechtigung hat.<br />*Wenn benutzerdefinierte Spalten unter „Zielspalte“ nicht erscheinen, wurde der <a href="%s" target="_blank">Suchindex<i class="fa fa-external-link"></i></a> nicht festgelegt. Bitte prüfen Sie den Inhalt des Linkziels und nehmen Sie die Einstellung vor.',
        'description_custom_view_grid_filters' => 'Legen Sie die Spalten fest, die im „Filter“ oben in der Ansicht als Auswahl angezeigt werden sollen.<br/>*Wenn Sie die Standardfelder des Systems anzeigen möchten, fügen Sie dieser Liste keine Spalten hinzu.<br/>*Wenn benutzerdefinierte Spalten unter „Zielspalte“ nicht erscheinen, wurde der <a href="%s" target="_blank">Suchindex<i class="fa fa-external-link"></i></a> nicht festgelegt. Bitte prüfen Sie den Inhalt des Links und nehmen Sie die Einstellung vor.',
        'description_custom_view_summary_filters' => '<br/>*Dieser „Filter“ schränkt die Daten vor der Auswertung ein, nicht die ausgewerteten Ergebnisse.',
        'help' => [
            'custom_view_type' => 'Systemansicht: Eine Ansicht, die allen Benutzern dieser Tabelle zur Verfügung steht. Benutzeransicht: Eine Ansicht, die nur dem Benutzer zur Verfügung steht, der sie erstellt hat.',
            'grid_preset' => 'Stellt diese Spalte in der Datenliste mit der gewählten Vorlage dar.<br/>Hat Vorrang vor der Spalteneinstellung.<br/>Mit der Stift-Schaltfläche können Sie eine Vorlage erstellen oder bearbeiten.',
            'sort_type' => 'Legt fest, ob aufsteigend oder absteigend sortiert wird.',
            'sort_order_summaries' => 'Sortiert die abzurufenden Daten.<br />Sortiert aufsteigend nach den Nummern aus „Gruppierungsspalte“ und „Summenspalte“.',
            'use_view_infobox' => 'Bei JA können Sie oben in der Ansicht eine Infobox einrichten, in die Sie Geschäftsinformationen und Mitteilungen an die Benutzer eintragen können.',
            'view_infobox_title' => 'Geben Sie den Titel ein, der in der Infobox angezeigt werden soll.',
            'view_infobox' => 'Bitte geben Sie das HTML ein, das in der Infobox angezeigt werden soll. *Bilder und Skripte können nicht eingegeben werden.',
            'order' => 'Anzeigereihenfolge der Menüschaltflächen der benutzerdefinierten Ansicht.',
            'kanban_group_column' => 'Die Optionen dieser Spalte werden zu den Kanban-Spalten.<br/>*Nur Auswahlspalten mit Einfachauswahl können gewählt werden. Wenn „Wie die Spalten des Boards gebildet werden“ auf „Aus den Status des Workflows“ steht, wird diese Einstellung nicht verwendet.',
            'kanban_swimlane_column' => 'Teilt das Board waagerecht nach dem Wert dieser Spalte auf.<br/>*Ist nichts festgelegt, wird das Board ohne Aufteilung angezeigt.',
            'kanban_editable' => 'Bei JA wird beim Ziehen einer Karte in eine andere Spalte der Wert von „Spalte für die Kanban-Spuren“ aktualisiert.<br/>*Benutzer ohne Bearbeitungsberechtigung können auch bei JA nicht ziehen.',
            'inline_edit_enabled' => 'Bei NEIN wird die Inline-Bearbeitung in der Datenliste dieser Ansicht nicht verwendet. Die Massenbearbeitung und die Bearbeitungsseite der Daten bleiben wie bisher verfügbar.<br/>*Steht „Inline-Bearbeitung in der Datenliste verwenden“ in den Systemeinstellungen auf NEIN, ist die Inline-Bearbeitung auch bei JA nicht möglich.',
            'kanban_max_count' => 'Maximale Anzahl der auf dem Board dargestellten Datensätze. Eine große Anzahl verlangsamt die Seite.',
            'gantt_start_column' => 'Die Datumsspalte, an der ein Balken beginnt.',
            'gantt_end_column' => 'Die Datumsspalte, an der ein Balken endet.<br/>*Ein Datensatz, dessen Datum überschritten ist und dessen Fortschritt unter 100 liegt, wird mit einem roten Rahmen als überfällig angezeigt.',
            'gantt_color_column' => 'Die Balken werden nach den Werten dieser Spalte eingefärbt.<br/>*Die in der Wertfarben-Einstellung der Spalte festgelegten Farben werden unverändert verwendet.',
            'gantt_progress_column' => 'Der Fortschritt (%) wird als dunklere Überlagerung im Balken dargestellt.',
            'gantt_group_column' => 'Die Zeilen werden nach den Werten dieser Spalte gruppiert.<br/>*Bei einer Spalte mit Tabellenverweis (z. B. eine Meilensteintabelle) wird die Datumsspalte der Zieltabelle, deren Spaltenname oder Anzeigename „Frist“, „due“, „deadline“, „期限“ o. Ä. enthält, als Frist mit einer Raute angezeigt. Gibt es keine solche Spalte, wird die letzte Datumsspalte verwendet.',
            'gantt_parent_column' => 'Wählen Sie eine Spalte, die auf diese Tabelle selbst verweist; untergeordnete Datensätze werden dann eingerückt unter ihrem übergeordneten Datensatz angezeigt.',
            'gantt_assignee_column' => 'Wählen Sie eine Benutzerspalte, um in jeder Zeile einen Avatar anzuzeigen.',
            'gantt_max_count' => 'Maximale Anzahl der im Diagramm dargestellten Datensätze (10–2000, Standard 500).',
            'kanban_source' => 'Woher die Kanban-Spalten stammen.<br/>*Aus einer Auswahlspalte: Ihre Optionen werden zu den Spalten.<br/>*Aus dem Workflow: Die Status des auf diese Tabelle angewendeten Workflows werden zu den Spalten. Beim Ziehen einer Karte öffnet sich die Workflow-Aktion, die zu diesem Status führt; eine Verschiebung, die der Workflow nicht erlaubt, wird abgelehnt.',
            'kanban_wip_enforce' => 'Was geschieht, wenn eine Karte in einer Spalte abgelegt wird, die ihr WIP-Limit bereits erreicht hat.<br/>„Erlauben“ behält das bisherige Verhalten bei: Der Spaltenkopf wird rot und die Karte wird trotzdem verschoben.<br/>„Vorher nachfragen“ zeigt eine Bestätigung und verschiebt die Karte nur, wenn Sie zustimmen.<br/>„Nicht erlauben“ graut die volle Spalte beim Ziehen aus und lehnt das Ablegen ab.<br/>*Spalten ohne WIP-Limit sind nie betroffen.<br/>*Karten, die „Als dringend geltende Werte“ entsprechen, sind von dieser Regel ausgenommen, werden aber mitgezählt – die Spalte bleibt also sichtbar über ihrem Limit.',
            'kanban_policies' => 'Eine Regel, die im Spaltenkopf angezeigt wird – fahren Sie mit der Maus über die Markierung, um sie zu lesen.<br/>Beispiel: Schreiben Sie bei der Spalte „Test“ „Alle Punkte des Testplans abgezeichnet, bevor es weitergeht“, und die Abschlussbedingung ist für das ganze Team sichtbar.<br/>*Die Zielspalte wird aus den Werten der Tabelle (oder den Status des Workflows) ausgewählt.<br/>*Eine Einstellung, die nicht zu den aktuell angezeigten Spalten passt, wird ignoriert.',
            'kanban_wips' => 'Maximale Anzahl von Karten, die eine Spalte enthalten darf. Die Zielspalte wird aus den Werten der Tabelle (oder den Status des Workflows) ausgewählt, nie von Hand eingegeben.<br/>*Eine Spalte über ihrem Limit erhält einen roten Spaltenkopf.<br/>*Eine Einstellung, die nicht zu den aktuell angezeigten Spalten passt, wird ignoriert.<br/>*Eine Anzahl von Karten liegt zwischen 1 und 999. Mit „WIP-Limit zählen nach (Zahlenspalte)“ geben Sie das Limit der Summe dieser Spalte ein (es darf über 999 liegen).',
            'kanban_done_keys' => 'Spalten, die „erledigt“ bedeuten, ausgewählt aus den Werten der Tabelle.<br/>*Bei diesen Datensätzen stoppt der Fristen-Countdown, und sie werden in der Übersichtsleiste als „Erledigt“ gezählt.<br/>*Auf einem Workflow-Board gilt jeder als abgeschlossen markierte Status bereits als erledigt, daher muss hier nichts festgelegt werden.<br/>*Eine Einstellung, die nicht zu den aktuell angezeigten Spalten passt, wird ignoriert.',
            'kanban_title_column' => 'Spalte, die als fetter Titel auf der Karte angezeigt wird.<br/>*Wenn festgelegt, wird die Datensatzbezeichnung als Link oben auf der Karte angezeigt.<br/>*Wenn nicht festgelegt, wird die Datensatzbezeichnung selbst zum Titel.',
            'kanban_assignee_column' => 'Spalte mit der zuständigen Person.<br/>*Wird mit einem Avatar unten auf der Karte angezeigt; Karten ohne Wert zeigen „Nicht zugewiesen“.<br/>*Wird auch von der Übersichtsleiste, dem Filter „Nur nicht zugewiesene“ und der Massenzuweisung verwendet.<br/>*<b>Bleibt sie leer</b>, hat das Board keinen Avatar, keine Kachel „Nicht zugewiesen“, keinen Filter „Nur nicht zugewiesene“, keine Massenzuweisung, keine Bearbeitung der zuständigen Person auf der Karte und keine automatische Zuweisung. Auch die Schaltfläche „Meine“ entfällt, sofern unter „Spalte, die die Schaltfläche „Meine“ auswertet“ keine Spalte angegeben ist.',
            'kanban_mine_column' => 'Welche Spalte die Schaltfläche „Meine“ in der Werkzeugleiste auswertet, um zu entscheiden, dass eine Karte Ihnen gehört.<br/>*Ist nichts festgelegt, wird die Spalte für die zuständige Person verwendet. Wählen Sie die Spalte der antragstellenden Person, um das Board auf die von Ihnen eingereichten Vorgänge einzugrenzen.<br/>*Benutzer- und Organisationsspalten können verwendet werden, ebenso eine Spalte, die auf eine Tabelle mit genau einer Benutzerspalte verweist (die mit Ihnen verknüpften Zeilen werden darüber gefunden).<br/>*Kann die Spalte nicht erkennen, wer die Seite ansieht (z. B. eine einfache Auswahl), wird die Schaltfläche nicht angezeigt.',
            'kanban_filter_columns' => 'Wählen Sie nur die Spalten aus, die der Filterbereich anbieten soll. Sie werden in der Reihenfolge Ihrer Auswahl angezeigt.<br/>*Ist nichts festgelegt, wird jede vom Board gelesene Spalte angeboten (gruppierbare Spalten, die zuständige Person, die Kartenfelder usw.), was bei einer breiten Tabelle eine lange Liste ergibt.<br/>*Stichwortfeld, Gruppierung, Swimlane und die Kontrollkästchen werden unabhängig von dieser Einstellung immer angezeigt.',
            'kanban_limit_column' => 'Die Datumsspalte für die Frist.<br/>*Aus der Differenz zur aktuellen Zeit zeigt die Karte ein Badge „noch“, „bald fällig“ oder „überfällig“.<br/>*Ein Datensatz, dessen Spalte als erledigt gilt, zeigt stattdessen „eingehalten“.<br/>*<b>Bleibt sie leer</b>, hat das Board kein Fristen-Badge, keine Kachel „Überfällig“, keinen Filter „Nur überfällige“ und keine Bearbeitung der Frist auf der Karte.',
            'kanban_sum_column' => 'Zeigt die Summe dieser Zahlenspalte unter dem Spaltenkopf an.<br/>Beispiel: Wählen Sie einen Betrag, und der Spaltenkopf zeigt „Genehmigung Geschäftsführung &yen;34,700,000“, sodass das in einer Spalte festsitzende Geld auf einen Blick sichtbar ist.<br/>*Nur zur Anzeige – das WIP-Limit wird nicht beeinflusst.<br/>*Ziffern und Währungszeichen folgen der Einstellung dieser Spalte.<br/>*Beim Filtern des Boards werden nur die auf dem Bildschirm verbleibenden Karten summiert.',
            'kanban_blocked_keys' => 'Werte, die bedeuten, dass die Arbeit ins Stocken geraten ist. Ihre Karten erhalten einen roten Rand und eine Fahne, und „Blockiert“ wird zur KPI-Leiste und zum Filterbereich hinzugefügt.<br/>Beispiel: „Zurückgestellt“ und „Zurückgewiesen“ einer Statusspalte oder „Ja“ einer eigenen Spalte für Blockierungen.<br/>*Es muss nicht die Spalte sein, nach der die Tafel gruppiert ist – jeder Wert jeder Spalte kann gewählt werden.<br/>*So lässt sich laufende Arbeit von ins Stocken geratener Arbeit unterscheiden.',
            'kanban_expedite_keys' => 'Werte, die eine dringende Unterbrechung bedeuten. Ihre Karten erhalten einen auffälligen Rahmen, und wenn die Tafel nach derselben Spalte in Bahnen aufgeteilt ist, wird diese Bahn oben fixiert.<br/>Beispiel: „Dringend“ einer Prioritätsspalte.<br/>*Expresskarten werden von „Verschieben in eine volle Spalte“ nie abgewiesen – entsprechend der üblichen Kanban-Regel, dass eine Unterbrechung das Limit überschreiten darf. Sie werden dennoch mitgezählt, sodass die Kosten der Unterbrechung sichtbar bleiben.<br/>*Werden viele Werte als Express markiert, verliert die Markierung ihren Sinn – beschränken Sie sich auf ein oder zwei.',
            'kanban_hide_keys' => 'Spalten der Tafel für die gewählten Werte werden nicht angezeigt.<br/>Beispiel: Lassen Sie „Erledigt“ und „Abgebrochen“ weg, dann enthält die Tafel nur die noch laufende Arbeit.<br/>*Ihre Datensätze werden gar nicht gelesen, daher wird die Tafel bei einer großen Tabelle allein dadurch deutlich schneller.<br/>*Sie werden auch bei Summen, Durchschnitten und der KPI-Leiste nicht berücksichtigt.<br/>*Bei einer Workflow-Tafel verschwindet die Karte von der Tafel, wenn ein Datensatz in einen ausgeblendeten Status verschoben wird (der Datensatz selbst bleibt unverändert).<br/>*Die Spalte „Nicht festgelegt“ kann nicht ausgeblendet werden.<br/>*Eine Einstellung, die nicht zu den aktuell angezeigten Spalten passt, wird ignoriert.',
            'kanban_col_count' => 'Wie viele Karten jede Spalte zu Beginn lädt.<br/>0 (leer) behält das bisherige Verhalten bei: eine Abfrage für die gesamte Tafel, bis zur maximalen Anzahl an Datensätzen.<br/>Bei 50 lädt jede Spalte 50 Karten, darunter erscheint eine Schaltfläche „Mehr laden“.<br/>*Anzahlen, Summen, durchschnittliche Tage und die KPI-Leiste werden dann über die gesamte Tabelle ermittelt, nicht nur über die gerade geladenen Karten.<br/>*Empfohlen, sobald eine Tabelle Tausende von Datensätzen enthält – die maximale Anzahl an Datensätzen begrenzt die Tafel dann nicht mehr.<br/>*Mit der in der Ansicht festgelegten Swimlane bleibt dies erhalten: Jede Zelle (Spalte × Bahn) zeigt dann ihre eigene, über die gesamte Tabelle ermittelte Anzahl.<br/>*Bei einem Filter, einer Stichwortsuche, einer anderen Gruppierung oder einer auf dem Bildschirm statt in der Ansicht gewählten Swimlane wird nur über die bereits geladenen Karten ausgewertet.',
            'kanban_col_age' => 'Zeigt unter der Spaltenüberschrift an, wie viele Tage die Karten dieser Spalte im Durchschnitt dort liegen.<br/>*So erkennen Sie, an welchem Schritt sich die Arbeit staut.<br/>*Gezählt ab dem Zeitpunkt, an dem der Datensatz seinen Status erreicht hat (Workflow-Tafel), sonst ab der letzten Änderung.',
            'kanban_progress_column' => 'Zahlenspalte, die als Fortschrittsbalken unter dem Kartentitel angezeigt wird.<br/>*0–49 % blau, 50–99 % orange, 100 % grün.<br/>*Karten mit leerem Wert erhalten keinen Balken.',
            'kanban_progress_max' => 'Der Wert, der für den Fortschrittsbalken als 100 % gilt.<br/>Beispiel: 100 für einen Prozentwert, 10 für einen Prozess mit zehn Schritten.<br/>*Standardwert ist 100.',
            'kanban_history' => 'Zeigt den Workflow-Verlauf – wann, wer und welche Aktion – im Detailbereich der Karte an.<br/>*Wird nur für die geöffnete Karte geladen, daher bleibt die Tafel selbst so schnell wie zuvor.<br/>*Wird nur bei Tabellen angezeigt, die einen Workflow verwenden.',
            'kanban_wip_column' => 'Zählt das WIP-Limit als Summe dieser Zahlenspalte statt als Anzahl der Karten.<br/>Beispiel: Wählen Sie eine Menge, dann zeigt die Spaltenüberschrift „1550/1200“.<br/>*Leer lassen, um weiterhin Karten zu zählen.<br/>*Es können nur Spalten vom Typ Ganzzahl, Dezimalzahl und Währung gewählt werden.',
            'kanban_limit_warn' => 'Eine Karte, deren Frist näher als diese Anzahl Stunden liegt, wird gelb.<br/>Beispiel: 2 für ein Support-Ticket, 48 (= 2 Tage) für einen Liefertermin.<br/>*Leer bedeutet 2 Stunden.',
            'kanban_age_steps' => 'Drei aufsteigende Tageszahlen, durch Kommas getrennt, bei denen der Kartenrand gelb, orange und rot wird.<br/>Beispiel: 1,2,3 für ein Ticket, 3,7,14 für einen langen Prozess.<br/>*Alles, was nicht aus drei aufsteigenden Zahlen besteht, wird als 1,2,3 behandelt.',
            'kanban_age_column' => 'Datumsspalte, ab der die vergangenen Tage gezählt werden (zum Beispiel das Eröffnungsdatum).<br/>*Der linke Rand der Karte wird nach Alter eingefärbt (1 Tag gelb, 2 Tage orange, 3 Tage oder mehr rot).<br/>*Wird auch für die Auswertung „Durchschn. vergangene Tage“ verwendet.',
            'kanban_ai_column' => 'Spalte, anhand derer ein empfohlener Bearbeiter ermittelt wird (zum Beispiel die zuständige Gruppe).<br/>*Die Person, die diesen Wert am häufigsten bearbeitet, wird für nicht zugewiesene Karten empfohlen.<br/>*Die Schaltfläche „Automatisch zuweisen“ erscheint nur, wenn sowohl diese Spalte als auch „Spalte für den Bearbeiter“ festgelegt sind.',
            'kanban_cover_column' => 'Bildspalte, die als Titelbild oben auf der Karte angezeigt wird.<br/>*Datensätze ohne Bild werden ohne Titelbild angezeigt.<br/>*Sind mehrere Bilder gespeichert, wird das erste verwendet.<br/>*Das Bild selbst wird im Bearbeitungsformular der Daten in diese Spalte hochgeladen.',
            'kanban_cover_fit' => 'Wie das Titelbild in seinem Rahmen sitzt.<br/>*„Füllen“ bedeckt den gesamten Rahmen und schneidet Überstehendes ab.<br/>*„Ganzes Bild einpassen“ zeigt das vollständige Bild mit seitlichem Rand.',
            'kanban_labels_column' => 'Auswahlspalte, die als farbige Labels oben auf der Karte angezeigt wird.<br/>*Auch eine Spalte mit Mehrfachauswahl ist möglich: Jeder Wert erhält ein eigenes Label.<br/>*Die Spalte wird außerdem zum Filterbereich hinzugefügt und findet Karten, die eines der Labels tragen.',
            'kanban_labels_style' => 'Wie die Labels aussehen.<br/>*„Chip“ ist ein kleines Label mit Text, „Farbbalken“ ist ein schmaler farbiger Streifen (im Trello-Stil).',
            'kanban_badge_column' => 'Spalte, die als kleines Abzeichen oben rechts auf der Karte angezeigt wird (eine Anzahl, Punkte, eine Nummer …).<br/>*Datensätze mit leerem Wert zeigen kein Abzeichen.',
            'kanban_kpi' => 'Bei JA wird über der Tafel eine Leiste mit Anzahlen angezeigt.',
            'kanban_quickadd' => 'Bei JA erhält jede Spalte ein Eingabefeld, das mit der Eingabetaste einen Datensatz anlegt.<br/>*Ausgefüllt werden nur die Bezeichnungsspalte und der Wert dieser Spalte.',
            'kanban_bulk' => 'Bei JA lassen sich mit Umschalt+Klick mehrere Karten auswählen und gemeinsam ändern.',
            'kanban_editform' => 'Bei JA öffnet ein Klick auf eine Karte das Bearbeitungsformular dieses Datensatzes über der Tafel. Beim Speichern wird das Formular geschlossen und nur diese Karte neu gezeichnet.<br/>*Wird Benutzern ohne Bearbeitungsrecht nicht angezeigt.<br/>*Bei NEIN bestimmt die Einstellung „Detailbereich“ unten, was ein Klick bewirkt.',
            'kanban_drawer' => 'Bei JA öffnet ein Klick auf eine Karte rechts einen Detailbereich.<br/>*Bei NEIN wird stattdessen die Seite des Datensatzes geöffnet.<br/>*Ist „Bearbeitungsformular öffnen“ oben ebenfalls JA, öffnet der Klick das Formular, und der Detailbereich wird über die Schaltfläche „i“ oben rechts auf der Karte geöffnet.',
            'kanban_position' => 'Wo auf der Karte diese Spalte angezeigt wird.',
            'kanban_style' => 'Stellt diese Spalte auf der Karte mit der gewählten Vorlage dar.<br/>Dies hat Vorrang vor der Spalteneinstellung.<br/>Über die Stift-Schaltfläche können Sie eine Vorlage anlegen oder bearbeiten.<br/>Bleibt das Feld leer, folgt die Karte der Spalteneinstellung; ist dort nichts festgelegt, wird „Name und Wert“ angezeigt.',
            'kanban_icon' => 'Ein Font-Awesome-Klassenname, zum Beispiel fa-phone.<br/>Um jeder Option ein eigenes Symbol zu geben, geben Sie durch Kommas getrennte Paare „Wert:Klasse“ ein.<br/>Beispiel: phone:fa-phone,mail:fa-envelope,chat:fa-comments',
        ],
