        'help' => 'Eine neue Funktion ist anfangs deaktiviert. Eine deaktivierte Funktion erscheint nicht im Menü, und ihre Seiten lassen sich auch nicht über die URL öffnen. Ihre Daten bleiben erhalten; wird sie wieder aktiviert, ist alles wie vorher. Systemadministratoren können aktivierte Funktionen jederzeit nutzen.',
