        'features' => [
            'file_server' => 'Dateifreigabe',
            'file_server_help' => 'Arbeitsbereiche, Ordner, Versionen und Freigabelinks. Beim Deaktivieren werden die Dateien nicht entfernt. Erstellen Sie nach dem Aktivieren auf der Seite „Dateifreigabe“ einen Arbeitsbereich und fügen Sie Mitglieder hinzu (Arbeitsbereiche erstellen Systemadministratoren).',
            'studio' => 'Studio',
            'studio_help' => 'Bildschirmliste, Erstellen von Bildschirmen und die Smartphone-App (/app).',
            'api_keys' => 'API-Schlüssel der Benutzer',
            'api_keys_help' => 'Mit „Alle Benutzer“ kann jeder eigene Schlüssel erstellen. Die Benutzer der ausgewählten Rollengruppen erstellen eigene API-Schlüssel. Ein Schlüssel kann nur, was der Benutzer darf, und zwar im für den Schlüssel gewählten Umfang (nur lesen, bestimmte Tabellen). Ein Schlüssel hat ein Ablaufdatum und kann auf bestimmte IP-Adressen oder ein Client-Zertifikat beschränkt werden. Ist dies deaktiviert, funktioniert kein Schlüssel (die Schlüssel bleiben erhalten).',
            'mcp' => 'MCP (Verbindung von einer KI)',
            'mcp_help' => 'Eine KI wie Claude durchsucht und liest die Daten von Exment (vorerst nur lesend). Sie meldet sich wie die API an (OAuth oder ein API-Schlüssel des Benutzers) und sieht nur, was der Benutzer sehen darf. Nur für Benutzer der ausgewählten Rollengruppen. Was die KI getan hat, steht im Vorgangsprotokoll als „MCP“.',
            'safety_check' => 'Sicherheitsabfrage',
            'data_maintenance' => 'Datenpflege',
            'data_maintenance_help' => 'Die Administratoren einer Tabelle bereinigen deren Daten auf einmal (derzeit: Anhänge auf einmal löschen). Gelöschte Dateien können nicht wiederhergestellt werden. Benutzer, die die Tabelle ändern dürfen, können die Funktion verwenden.',
            'safety_check_help' => 'Fragt ab, ob die Benutzer in Sicherheit sind, etwa nach einem Erdbeben (Seite zum Senden, Antwortseite, automatischer Versand anhand von Erdbebenmeldungen, Antworten über LINE). Beim Deaktivieren bleiben Gesendetes und Antworten erhalten.',
            'tuning' => 'Optimierung',
            'tuning_help' => 'Prüfung der Einstellungen, die die Website schneller machen („Optimierung“ unter „Einstellungen: System“). Nur für Systemadministratoren. Die empfohlenen Änderungen betreffen Servereinstellungen wie php.ini und .env.',
            'maintenance_mode' => 'Wartungsmodus',
            'maintenance_mode_help' => 'Während Sie Daten migrieren oder Plugins installieren, haben nur Systemadministratoren Zugang. Alle anderen sehen die Seite „Wartungsarbeiten“. Nur Systemadministratoren können den Modus ein- und ausschalten.',
            'scheduled_jobs' => 'Geplante Aufgaben',
            'scheduled_jobs_help' => 'Die Aufgaben, die der Cron des Servers ausführt (schedule:run): ihre Liste, ihre letzten Läufe und „Jetzt ausführen“. Die Systemadministratoren werden benachrichtigt, wenn eine Aufgabe mehrmals hintereinander fehlschlägt. Die Läufe werden nur gespeichert, solange die Funktion genutzt wird. Nur Systemadministratoren können sie nutzen.',
            'data_sync' => 'Datensynchronisierung',
            'data_sync_help' => 'Importiert die Daten anderer Dienste (kintone, Backlog, ...) laufend in Exment-Tabellen, auch für einen Umzug zu Exment. Der Teil jedes Dienstes kommt als Plugin (Konnektor). Nur Systemadministratoren.',
            'api_members' => 'API für die Mitglieder von Organisationen und Rollengruppen',
            'api_members_help' => 'Mit der API die Benutzer einer Organisation und die Benutzer und Organisationen einer Rollengruppe lesen und ändern. Nur Systemadministratoren und Benutzer mit der Berechtigung, Rollengruppen zu verwalten. Eine Rollengruppe mit Systemberechtigung können nur Systemadministratoren ändern.',
            'api_rate_raise' => 'Vorübergehende Erhöhung des API-Limits',
            'api_rate_raise_help' => 'Erlaubt einem Benutzer oder einem API-Client bis zu einem Zeitpunkt mehr API-Anfragen pro Minute, z. B. für einen Import oder eine Datenübernahme. Danach gilt wieder das normale Limit. Nur für Systemadministratoren.',
            'encrypted_columns' => 'Verschlüsselte Spalten',
            'encrypted_columns_help' => 'Erlaubt, eine Spalte einer Tabelle verschlüsselt in der Datenbank zu speichern (ein- und mehrzeiliger Text, E-Mail, URL). Der Schlüssel ist DATA_ENCRYPTION_KEYS in .env, nicht in der Datenbank und nicht in einer Sicherung. Eine verschlüsselte Spalte kann nicht für Teilsuche, Sortierung oder Summen verwendet werden.',
            'trash' => 'Papierkorb',
            'trash_help' => 'Zeigt die gelöschten Daten aller Tabellen auf einer Seite, um sie wiederherzustellen oder endgültig zu löschen. Für Benutzer, die die gelöschten Daten einer Tabelle sehen dürfen.',
            'teams_notify' => 'Teams-Benachrichtigungen (persönlicher Chat)',
            'teams_notify_help' => 'Benachrichtigungen an den Teams-Chat einer Person über einen Teams-Workflow (Power Automate). Legen Sie die Adresse des Workflows in den Systemeinstellungen fest.',
            'webhook_notify' => 'Webhook-Benachrichtigungen (JSON)',
            'webhook_notify_help' => 'Benachrichtigungen können die Daten als JSON an eine beliebige URL senden („Webhook (JSON)“). Die Werte der Daten werden außerhalb der Website gesendet.',
            'lineworks_notify' => 'Benachrichtigungen an LINE WORKS',
            'lineworks_notify_help' => 'Sendet Benachrichtigungen von einem LINE WORKS Bot an einen Kanal oder an jeden Benutzer. Die Daten verlassen die Site, daher anfangs aus. Legen Sie die LINE WORKS App in der Systemeinstellung fest.',
            'mail_oauth' => 'Mail-OAuth-Authentifizierung (Microsoft 365, Google)',
            'mail_oauth_help' => 'E-Mails mit OAuth 2.0 (XOAUTH2) statt mit Passwort senden. Microsoft 365 stellt die SMTP-Standardauthentifizierung ein.',
            'browser_log' => 'Browser-Protokoll',
            'browser_log_help' => 'Zur Beantwortung von Anfragen senden die Browser der Benutzer Skriptfehler, fehlgeschlagene Anfragen und (wenn gewählt) geöffnete Seiten. Eingegebene Werte und Seitentexte werden nie gesendet. Wählen Sie die Rollengruppen, deren Benutzer senden.',
            'mcp_log' => 'MCP-Protokoll',
            'mcp_log_help' => 'Speichert die Aufrufe von KI (MCP) und zeigt sie in der Protokollverwaltung: Werkzeug, Benutzer, Zeit, Dauer, Größe der Antwort und den Grund einer Ablehnung (Geheimnisse maskiert). Systemadministratoren und Rollengruppen mit „Audit“ können es lesen.',
        ],
